from app import sessions, store


def tokens_for(user_id):
    return sorted(store.TOKENS.get(user_id, ()))


def revoke_all(user_id):
    """Log the user out everywhere.

    Sessions are the source of truth (middleware checks them); the tokens
    table is a mirror rebuilt from sessions, so both must be cleared.
    """
    sessions.end_all(user_id)
    store.delete_tokens(user_id)
